/* ===== GlobalStone — Global Commercial Real Estate Services ===== */
/* CSS Variables */
:root {
  --color-navy: #0A1628;
  --color-navy-light: #111F38;
  --color-navy-lighter: #1A2D4A;
  --color-white: #FFFFFF;
  --color-off-white: #F4F5F6;
  --color-gray-100: #E8E9EB;
  --color-gray-200: #D1D3D7;
  --color-gray-300: #A8ACB3;
  --color-gray-400: #7D828C;
  --color-gray-500: #5A606B;
  --color-gray-600: #3D424A;
  --color-gold: #C4A44A;
  --color-gold-light: #D4B96A;
  --color-gold-dark: #A8892E;
  --color-teal: #0D5E5C;
  --color-teal-light: #1A7A78;
  --color-forest: #003F2D;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-display: 'Georgia', 'Times New Roman', serif;
  --max-width: 1280px;
  --nav-height: 72px;
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: var(--font-sans);
  color: var(--color-navy);
  background: var(--color-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 { line-height: 1.2; font-weight: 700; }
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }

.display-text {
  font-family: var(--font-display);
  font-weight: 700;
}
.text-gold { color: var(--color-gold); }
.text-teal { color: var(--color-teal); }
.text-gray { color: var(--color-gray-400); }
.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-center { text-align: center; }
.font-semibold { font-weight: 600; }
.uppercase { text-transform: uppercase; letter-spacing: 0.08em; }

/* ===== Container & Sections ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}
.section {
  padding: 5rem 0;
}
.section-sm {
  padding: 3rem 0;
}
.section-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-gold);
  margin-bottom: 0.75rem;
}
.section-title {
  margin-bottom: 1rem;
}
.section-subtitle {
  font-size: 1.125rem;
  color: var(--color-gray-500);
  max-width: 720px;
  line-height: 1.7;
}
.bg-navy { background: var(--color-navy); color: var(--color-white); }
.bg-off-white { background: var(--color-off-white); }
.bg-navy-light { background: var(--color-navy-light); color: var(--color-white); }

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: 4px;
  transition: all var(--transition);
  line-height: 1;
  white-space: nowrap;
}
.btn-primary {
  background: var(--color-gold);
  color: var(--color-navy);
}
.btn-primary:hover {
  background: var(--color-gold-dark);
  color: var(--color-white);
}
.btn-outline {
  border: 2px solid var(--color-gold);
  color: var(--color-gold);
  background: transparent;
}
.btn-outline:hover {
  background: var(--color-gold);
  color: var(--color-navy);
}
.btn-outline-white {
  border: 2px solid var(--color-white);
  color: var(--color-white);
  background: transparent;
}
.btn-outline-white:hover {
  background: var(--color-white);
  color: var(--color-navy);
}
.btn-outline-navy {
  border: 2px solid var(--color-navy);
  color: var(--color-navy);
  background: transparent;
}
.btn-outline-navy:hover {
  background: var(--color-navy);
  color: var(--color-white);
}
.btn-arrow {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--color-gold);
  transition: gap var(--transition);
}
.btn-arrow:hover { gap: 0.7rem; }
.btn-arrow:hover i { color: var(--color-gold-dark); }

/* ===== Header & Navigation ===== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--color-navy);
  height: var(--nav-height);
  transition: background var(--transition);
}
.header.scrolled {
  background: rgba(10, 22, 40, 0.97);
  backdrop-filter: blur(12px);
  box-shadow: 0 1px 0 rgba(255,255,255,0.06);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--nav-height);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}
.logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--color-white);
  letter-spacing: -0.01em;
}
.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--color-gold);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  color: var(--color-navy);
  font-weight: 800;
  font-size: 1.1rem;
}
.logo-accent { color: var(--color-gold); }

/* Desktop Nav */
.nav-main { display: flex; align-items: center; gap: 0; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}
.nav-item { position: relative; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.6rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255,255,255,0.85);
  border-radius: 4px;
  transition: all var(--transition);
}
.nav-link:hover,
.nav-link.active {
  color: var(--color-white);
  background: rgba(255,255,255,0.06);
}
.nav-link.active { color: var(--color-gold); }
.nav-chevron {
  font-size: 0.65rem;
  transition: transform var(--transition);
}
.nav-item:hover .nav-chevron { transform: rotate(180deg); }

/* Nav CTA */
.nav-cta {
  margin-left: 1rem;
  padding: 0.5rem 1.25rem;
  font-size: 0.8125rem;
  font-weight: 600;
  background: var(--color-gold);
  color: var(--color-navy);
  border-radius: 4px;
  transition: all var(--transition);
}
.nav-cta:hover {
  background: var(--color-gold-dark);
  color: var(--color-white);
}

/* ===== Mega Menu ===== */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  width: 780px;
  background: var(--color-white);
  border-radius: 8px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.18);
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s ease;
  padding: 2rem;
}
.nav-item:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}
.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}
.mega-menu-col h4 {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-gray-400);
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--color-gray-100);
}
.mega-menu-link {
  display: block;
  padding: 0.55rem 0.75rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-navy);
  border-radius: 4px;
  transition: all var(--transition);
}
.mega-menu-link:hover {
  background: var(--color-off-white);
  color: var(--color-gold);
}

/* Mobile Nav Toggle */
.mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  cursor: pointer;
  z-index: 1001;
}
.mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-white);
  border-radius: 2px;
  transition: all var(--transition);
}
.mobile-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.mobile-toggle.active span:nth-child(2) { opacity: 0; }
.mobile-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* Mobile Nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-navy);
  z-index: 999;
  padding: calc(var(--nav-height) + 1.5rem) 1.5rem 2rem;
  overflow-y: auto;
}
.mobile-nav.active { display: block; }
.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  font-size: 1.1rem;
  color: rgba(255,255,255,0.85);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  font-weight: 500;
}
.mobile-nav-link:hover { color: var(--color-gold); }
.mobile-submenu {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.mobile-submenu.open { max-height: 600px; }
.mobile-submenu-title {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-gray-400);
  padding: 1rem 0 0.5rem 1rem;
}
.mobile-submenu-link {
  display: block;
  padding: 0.6rem 1rem;
  font-size: 0.95rem;
  color: rgba(255,255,255,0.7);
}
.mobile-submenu-link:hover { color: var(--color-gold); }
.mobile-nav-cta {
  margin-top: 1.5rem;
  display: block;
  text-align: center;
  padding: 0.8rem;
  background: var(--color-gold);
  color: var(--color-navy);
  font-weight: 600;
  border-radius: 4px;
  font-size: 0.95rem;
}

/* ===== Hero ===== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: var(--color-navy);
  overflow: hidden;
  padding-top: var(--nav-height);
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(10,22,40,0.95) 0%,
    rgba(10,22,40,0.75) 40%,
    rgba(13,94,92,0.4) 100%
  );
  z-index: 1;
}
.hero-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.6);
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 720px;
  padding: 3rem 0;
}
.hero .section-label { margin-bottom: 1rem; }
.hero h1 {
  color: var(--color-white);
  margin-bottom: 1.25rem;
  font-family: var(--font-display);
}
.hero-subtitle {
  font-size: 1.2rem;
  color: rgba(255,255,255,0.7);
  margin-bottom: 2rem;
  line-height: 1.7;
}
.hero-cta-group {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Hero variants */
.hero-sm {
  min-height: 50vh;
  padding-top: var(--nav-height);
}
.hero-sm .hero-content { padding: 2rem 0; }
.hero-sm h1 { font-size: clamp(1.75rem, 3.5vw, 2.75rem); }

/* ===== Hero Overlay Pattern ===== */
.hero-pattern {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 20% 50%, rgba(196,164,74,0.08) 0%, transparent 50%),
    radial-gradient(circle at 80% 20%, rgba(13,94,92,0.06) 0%, transparent 50%);
  z-index: 1;
}

/* ===== Page Header Hero (inner pages) ===== */
.page-hero {
  position: relative;
  background: var(--color-navy);
  padding: calc(var(--nav-height) + 3rem) 0 3rem;
  overflow: hidden;
}
.page-hero .hero-bg { z-index: 0; }
.page-hero .container { position: relative; z-index: 2; }
.page-hero h1 {
  color: var(--color-white);
  font-family: var(--font-display);
  margin-bottom: 1rem;
}
.page-hero p {
  color: rgba(255,255,255,0.7);
  font-size: 1.125rem;
  max-width: 640px;
  line-height: 1.7;
}
.page-hero-sm {
  padding: calc(var(--nav-height) + 2.5rem) 0 2rem;
}
.page-hero-sm h1 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }

/* ===== Breadcrumb ===== */
.breadcrumb {
  display: flex;
  gap: 0.5rem;
  font-size: 0.8125rem;
  color: var(--color-gray-400);
  margin-bottom: 1.5rem;
}
.breadcrumb a { color: var(--color-gold); }
.breadcrumb a:hover { text-decoration: underline; }
.breadcrumb span { color: var(--color-gray-400); }

/* ===== Featured Insights Section ===== */
.featured-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}
.insight-card {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  transition: all var(--transition);
}
.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(0,0,0,0.08);
}
.insight-card-img {
  width: 100%;
  height: 180px;
  object-fit: cover;
  background: var(--color-gray-200);
}
.insight-card-body { padding: 1.25rem; }
.insight-card-tag {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-teal);
  margin-bottom: 0.5rem;
}
.insight-card-title {
  font-size: 1.05rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 0.5rem;
  color: var(--color-navy);
}
.insight-card-card .insight-card-title:hover { color: var(--color-teal); }

/* ===== Announcement Banner ===== */
.announcement-banner {
  background: var(--color-navy-light);
  border-top: 1px solid rgba(255,255,255,0.06);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  padding: 2rem 0;
}
.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}
.announcement-text {
  font-size: 1.1rem;
  color: var(--color-white);
  font-weight: 500;
}
.announcement-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  background: var(--color-gold);
  border-radius: 50%;
  margin-right: 0.75rem;
}

/* ===== About Statement ===== */
.about-statement {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.about-overline {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-gold);
  margin-bottom: 0.75rem;
}
.about-text {
  font-size: 1.125rem;
  color: var(--color-gray-500);
  line-height: 1.8;
}
.about-img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  border-radius: 8px;
}

/* ===== What We Do (Tabbed Section) ===== */
.what-we-do-inner {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 3rem;
  margin-top: 2.5rem;
}
.wwd-tabs {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.wwd-tab {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.125rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-gray-500);
  border-radius: 6px;
  transition: all var(--transition);
  border-left: 3px solid transparent;
  text-align: left;
  width: 100%;
}
.wwd-tab:hover {
  color: var(--color-navy);
  background: var(--color-off-white);
}
.wwd-tab.active {
  color: var(--color-navy);
  background: var(--color-off-white);
  border-left-color: var(--color-gold);
}
.wwd-tab i { font-size: 1.1rem; transition: transform var(--transition); }
.wwd-tab.active i { color: var(--color-gold); }
.wwd-panels { position: relative; }
.wwd-panel {
  display: none;
  animation: fadeSlide 0.4s ease;
}
.wwd-panel.active { display: block; }
.wwd-panel-title {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 1rem;
  font-family: var(--font-display);
}
.wwd-panel-text {
  font-size: 1.1rem;
  color: var(--color-gray-500);
  line-height: 1.8;
  margin-bottom: 1.5rem;
}
.wwd-visual {
  margin-top: 2rem;
  border-radius: 8px;
  overflow: hidden;
  height: 240px;
  background: var(--color-gray-200);
}
.wwd-visual img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ===== Newsletter Section ===== */
.newsletter-inner {
  background: var(--color-navy);
  border-radius: 12px;
  padding: 3.5rem;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 3rem;
  align-items: center;
}
.newsletter-title {
  font-size: 1.75rem;
  color: var(--color-white);
  font-family: var(--font-display);
  margin-bottom: 0.75rem;
}
.newsletter-text { color: rgba(255,255,255,0.65); font-size: 1.05rem; }
.newsletter-form {
  display: flex;
  gap: 0.75rem;
}
.newsletter-input {
  padding: 0.75rem 1rem;
  font-size: 0.9375rem;
  border: 1px solid rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.08);
  color: var(--color-white);
  border-radius: 4px;
  min-width: 280px;
  font-family: var(--font-sans);
}
.newsletter-input::placeholder { color: rgba(255,255,255,0.4); }
.newsletter-input:focus {
  outline: none;
  border-color: var(--color-gold);
}

/* ===== Latest Insights ===== */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}
.insight-card-large { border: none; }
.insight-card-meta {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
  margin-top: 0.5rem;
}
.insight-card-link {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-top: 0.75rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-gold);
}

/* ===== Commitment Pillars ===== */
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}
.commitment-card {
  padding: 2rem 1.5rem;
  border-radius: 8px;
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  transition: all var(--transition);
  text-align: center;
}
.commitment-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(0,0,0,0.08);
  border-color: var(--color-gold);
}
.commitment-icon {
  font-size: 2rem;
  color: var(--color-gold);
  margin-bottom: 1rem;
}
.commitment-card h3 {
  font-size: 1.1rem;
  margin-bottom: 0.75rem;
}
.commitment-card p {
  font-size: 0.9rem;
  color: var(--color-gray-500);
  line-height: 1.6;
  margin-bottom: 1.25rem;
}

/* ===== Service Categories Grid ===== */
.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 2.5rem;
}
.service-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: 8px;
  padding: 2rem;
  transition: all var(--transition);
}
.service-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 32px rgba(0,0,0,0.08);
  border-color: var(--color-gold);
}
.service-card-icon {
  width: 48px;
  height: 48px;
  background: var(--color-off-white);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  color: var(--color-teal);
  margin-bottom: 1.25rem;
}
.service-card h3 { font-size: 1.15rem; margin-bottom: 0.75rem; }
.service-card p {
  font-size: 0.925rem;
  color: var(--color-gray-500);
  line-height: 1.65;
  margin-bottom: 1.25rem;
}
.service-card .btn-arrow { font-size: 0.875rem; }

/* ===== Capabilities Grid ===== */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 2.5rem;
}
.capability-card {
  background: var(--color-white);
