  padding: 3rem 0;
}
.section-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-gold);
  margin-bottom: 0.75rem;
}
.section-title {
  margin-bottom: 1rem;
}
.section-subtitle {
  font-size: 1.125rem;
