  align-items: center;
  justify-content: center;
  border-radius: 4px;
  color: var(--color-navy);
  font-weight: 800;
  font-size: 1.1rem;
}
.logo-accent { color: var(--color-gold); }

/* Desktop Nav */
.nav-main { display: flex; align-items: center; gap: 0; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}
.nav-item { position: relative; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.6rem 1rem;
